+static void jl_serialize_methtable_from_mod(ios_t *s, jl_typename_t *tn, int8_t iskw)
 {
     struct jl_serialize_methcache_from_mod_env env;
     env.s = s;
-    env.mod = mt->module;
-    env.name = mt->name;
+    env.mod = tn->module;
+    env.name = tn->name;
     env.iskw = iskw;
-    assert(mt->module);
+    assert(tn->module);
     if (iskw) {
-        if (!mt->kwsorter)
+        if (!tn->mt->kwsorter)
             return;
-        assert(mt->module == jl_gf_mtable(mt->kwsorter)->module);
